game = freshCombat("knight"); giveWeapon(); game.enemy.chargeIn = 99; game.enemy.hp = game.enemy.maxHp = 100000;
game.talents.k_bastion = 1; // v3.327.0 : Bastion (Garde 2 rounds) remplace Bouclier renforcé
