var kOff = g.CombatRoundSim.duelBudget(hdK, g.CLASS_SKILLS.knight, slimeDef, false, cfgOff, 1);
ok(Math.abs(kOn.rpm - kOff.rpm) < 1e-9 && Math.abs(kOn.rpt - kOff.rpt) < 1e-9, "sim : Chevalier strictement inchangé (mêlée)");

