  ok(game.combatRound.number === r0 && g.TouchDebug.actions[0].indexOf("= false") !== -1 && g.TouchDebug.actions[0].indexOf("busy") !== -1, "heroAction refusé, raison notée : " + g.TouchDebug.actions[0]);
  g.forceLeaveCombat();
