/* [127] v3.332.0 — Écran de retour (R-1) et fil rouge (F-1), conception Évolutions v1.0. */
console.log("\n[127] v3.332.0 — Écran de retour unique et fil rouge");
(function () {
  run("fullResetState(); game.playerName='R'; game.heroId='knight'; VillageBuildingManager.ensure(); EquipmentManager.recalcStats(); game.heroHp = game.heroMaxHp;");
  var FR = g.FilRouge, RM = g.ReturnManager, SQ = g.StoryQuestManager;

  // --- HUD : le fil rouge remplace le raccourci Ascension (F1) ---
  var hud = g.buildHudHTML();
  ok(typeof g.renderHudDock === "function" && typeof g.renderHudFilRouge === "undefined" && hud.indexOf("hud-ascension-badge") === -1, "F1 : le fil rouge remplace l'Ascension (v3.396.0 : c'est une bulle de raccourci)");
  ok(typeof g.renderHudAscensionBadge === "undefined", "F1 : l'ancien nom est retiré (v3.412.0, code mort)");

  // --- Préférences d'affichage (F4) ---
  ok(g.Prefs.get("filRouge") === true && g.Prefs.get("bossMoments") === true, "F4 : fil rouge et mises en scène actifs par défaut");
  g.Prefs.set("filRouge", false);
  g.Prefs._cache = null;
  ok(g.Prefs.get("filRouge") === false, "F4 : le réglage survit à une relecture (stockage de l'appareil)");
  g.Prefs.set("filRouge", true);

  // --- Arbitre (F2) ---
  var all = FR.all();
  ok(all.length >= 1 && all[all.length - 1].id === "idle", "F2 : la dernière proposition est toujours l'activité du monde");
  ok(all.every(function (a) { return a.title && typeof a.go === "function" && a.icon && a.goLabel; }), "F2 : chaque proposition a titre, icône, geste et libellé");
  ok(FR.next().id === "story", "F2 : partie neuve -> l'étape d'Histoire (" + FR.next().title + ")");

  // Histoire prête -> Réclamer passe devant
  var readySave = SQ.isCurrentStepReady;
  SQ.acceptStep("forest");
  SQ.isCurrentStepReady = function () { return true; };
  try { ok(FR.next().id === "claim" && FR.next().urgent === true, "F2 : récompense d'Histoire à réclamer en premier, marquée urgente"); }
  finally { SQ.isCurrentStepReady = readySave; }

  /* La première étape (« Le feu de camp ») est réellement prête dès qu'on l'accepte :
     pour la suite, l'étape est tenue « en cours » (acceptée, pas prête). */
  SQ.isCurrentStepReady = function () { return false; };

  // Mémoire en attente avant l'Histoire
  var pendSave = g.MemoryManager.getPendingLevels, tabSave = g.isTabUnlocked;
  g.MemoryManager.getPendingLevels = function () { return [4]; };
  g.isTabUnlocked = function () { return true; };
  try { ok(FR.next().id === "memory", "F2 : un choix de Mémoire passe avant l'étape d'Histoire"); }
  finally { g.MemoryManager.getPendingLevels = pendSave; g.isTabUnlocked = tabSave; }

  // Soin avant un combat d'Histoire
  var stepSave = SQ.getCurrentStep;
  SQ.getCurrentStep = function (c) { var s = stepSave.call(SQ, c); return s ? Object.assign({}, s, { linkTo: { section: "adventure", cardId: "adv_x" } }) : s; };
  g.game.heroHp = Math.floor(g.game.heroMaxHp * 0.4);
  try {
    ok(FR.next().id === "heal", "F2 : PV < 60 % avant un combat d'Histoire -> reprendre des forces");
    g.game.heroHp = g.game.heroMaxHp;
    ok(FR.next().id === "story", "F2 : PV pleins -> l'étape d'Histoire");
  } finally { SQ.getCurrentStep = stepSave; g.game.heroHp = g.game.heroMaxHp; }

  // Sans Histoire : Taverne, puis zones pleines
  var storySave = FR._story;
  FR._story = function () { return null; };
  try {
    var tvSave = g.TavernManager.getLevel, ctSave = g.TavernManager.getContracts, cdSave = g.TavernManager.canDeliver;
    g.TavernManager.getLevel = function () { return 2; };
    g.TavernManager.getContracts = function () { return [{ id: "c1", resourceId: "bois", quantity: 40, reward: 88, done: false, title: "t" }]; };
    g.TavernManager.canDeliver = function () { return true; };
    try { ok(FR.next().id === "tavern" && /88 or/.test(FR.next().reason), "F2 : contrat livrable -> la Taverne, avec la paie"); }
    finally { g.TavernManager.getLevel = tvSave; g.TavernManager.getContracts = ctSave; g.TavernManager.canDeliver = cdSave; }
    var cfSave = g.OfflineManager._countFullPlots;
    g.OfflineManager._countFullPlots = function () { return { full: 3, open: 4 }; };
    try { ok(FR.next().id === "plots", "F2 : la moitié des zones pleines -> récolter"); }
    finally { g.OfflineManager._countFullPlots = cfSave; }
  } finally { FR._story = storySave; SQ.isCurrentStepReady = readySave; }

  // Cache d'une seconde, invalidation
  FR.invalidate();
  var a1 = FR.get(), a2 = FR.get();
  ok(a1 === a2, "F-1 : get() garde sa proposition (le HUD se redessine à chaque image)");
  FR.invalidate();
  ok(FR.get() !== a1, "F-1 : invalidate() force le recalcul");

  // --- Retour : capture et comparaison (R2) ---
  g.game.village.site = { id: "tavern", targetLevel: 1, endsAt: Date.now() + 3600e3 };
  var ex = RM.capture();
  ok(ex.site && ex.site.id === "tavern" && typeof ex.hp === "number", "R2 : la photographie prend le chantier et les PV");
  ex.site.endsAt = Date.now() - 1000;
  ex.hp = g.game.heroHp - 120;
  var s = RM.complete({ produced: {}, crafted: {}, fullPlots: 0, openPlots: 0, ms: 7 * 3600e3 }, ex);
  ok(s.siteDone && s.siteDone.name === g.VILLAGE_BUILDINGS.tavern.name && s.siteDone.level === 1, "R2 : chantier terminé pendant l'absence");
  ok(s.hpGain === 120, "R2 : PV rendus par le feu");
  ok(RM.hasContent(s), "R2 : un retour sans production a quand même quelque chose à dire");
  ok(!RM.hasContent(RM.complete({ produced: {}, crafted: {}, ms: 1 }, RM.capture())), "R2 : rien de neuf -> pas d'écran");
  g.game.village.site = null;

  // --- R1 : jamais pendant un combat ---
  g.game.activeTab = "combat";
  ok(RM.request(s) === true && RM.hasPending(), "R1 : héros au combat -> le retour attend");
  ok(RM.flushPending() === false, "R1 : toujours engagé -> rien ne s'ouvre");
  g.game.activeTab = "campement";
  ok(RM.flushPending() === true && !RM.hasPending(), "R1 : héros libre -> l'écran s'ouvre");
  var st = g.getReturnScreenState();
  ok(st && st.summary === s, "R1 : l'écran porte le résumé attendu");
  var html = g.buildReturnScreenHTML();
  ok(html.indexOf("Pendant ton absence") !== -1 && html.indexOf("Chantier terminé") !== -1 && html.indexOf("au coin du feu") !== -1, "R2 : rubriques Chantier et Héros rendues");
  ok(html.indexOf("Ensuite") !== -1, "R2 : le fil rouge en pied d'écran");
  g.closeReturnScreen();

  // --- R3 : Livrer affiche le coût, Tout récolter ne dépense rien ---
  var tv2 = g.TavernManager.getLevel, ct2 = g.TavernManager.getContracts, cd2 = g.TavernManager.canDeliver;
  g.TavernManager.getLevel = function () { return 1; };
  g.TavernManager.getContracts = function () { return [{ id: "c1", resourceId: "bois", quantity: 40, reward: 88, done: false, title: "t" }]; };
  g.TavernManager.canDeliver = function () { return true; };
  try {
    g.openReturnScreen({ ms: 3600e3, produced: { bois: 30 }, crafted: {}, fullPlots: 1, openPlots: 3, tavernNew: true, hpGain: 0 });
    var h3 = g.buildReturnScreenHTML();
    ok(h3.indexOf("Tout récolter") !== -1 && h3.indexOf("Livrer 1 contrat") !== -1 && h3.indexOf("−40 Bois") !== -1, "R3 : deux gestes, le coût de la livraison affiché");
    g.closeReturnScreen();
  } finally { g.TavernManager.getLevel = tv2; g.TavernManager.getContracts = ct2; g.TavernManager.canDeliver = cd2; }

  // --- R5 : phrase du monde, selon les compagnons ---
  var line = RM.pickLine();
  ok(typeof line === "string" && line.length > 0, "R5 : une phrase du monde");
  ok(g.RETURN_WORLD_LINES.forest.length === 6 && g.RETURN_WORLD_LINES.desert.length === 6, "R5 : six phrases par monde");
  var unl = g.CompanionManager.isUnlocked;
  g.CompanionManager.isUnlocked = function () { return false; };
  try {
    var bad = 0;
    for (var i = 0; i < 40; i++) if (/Wenna/.test(RM.pickLine())) bad++;
    ok(bad === 0, "R5 : une phrase qui nomme Wenna n'apparaît pas avant son arrivée");
  } finally { g.CompanionManager.isUnlocked = unl; }

  // --- Boot : le résumé se fait en fin d'init (après le feu et le chantier) ---
  var boot = require("fs").readFileSync(ROOT + "/js/main/boot.js", "utf8");
  ok(boot.indexOf("OfflineManager.summarize()") > boot.indexOf("switchTab(game.activeTab"), "R-1 : résumé de retour après le premier écran posé");
})();


/* [128] v3.333.0 — Moments de boss et trophées (B-1, B-2), conception Évolutions v1.0. */
console.log("\n[128] v3.333.0 — Moments de boss : entrée, phase, coup final, trophées");
(function () {
  var BM = g.BossMomentManager;
  var game = freshCombat("knight"); giveWeapon();
  ok(g.game.bossTrophies && Object.keys(g.game.bossTrophies).length === 0, "partie neuve : aucun trophée");

  // Données : par nom d'abord (boss de donjon), puis par identifiant, lore d'élite en repli
  var basilic = { id: "slimeking", name: "\ud83d\udc51 Basilic", isBoss: true };
  var roi = { id: "slimeking", name: "Roi Slime géant", isBoss: true };
  ok(BM.cleanName(basilic) === "Basilic" && BM.getMoment(basilic).title === g.BOSS_MOMENTS.Basilic.title, "B6 : le Basilic est trouvé par son nom (base slimeking)");
  ok(BM.getMoment(roi).title === g.BOSS_MOMENTS.slimeking.title, "B6 : le Roi Slime par son identifiant");
  ok(BM.keyOf(basilic) !== BM.keyOf(roi), "B5 : Basilic et Roi Slime ont deux trophées distincts");
  var fil = { id: "araignee_marquee", name: "Fileuse aux yeux blancs", isBoss: true, isElite: true };
  ok(BM.getMoment(fil).intro === g.ELITE_DB.araignee_marquee.lore, "B6 : une élite sans réplique parle par sa lore");
  ok(g.getCompanionDef("wenna").lines.bossIntro && g.getCompanionDef("maddoc").lines.bossWin, "B6 : répliques de boss de Wenna et Maddoc");
  ok(g.getCompanionDef("maddoc", "affut").lines.bossIntro === g.getCompanionDef("maddoc", "tronc").lines.bossIntro, "B6 : les répliques de Maddoc valent pour ses deux voies");

  // Espions sur la vue
  var seen = { intro: [], phase: [], final: [] };
  var sI = g.showBossIntro, sP = g.showBossPhase, sF = g.showBossFinal;
  g.showBossIntro = function (e, mode) { seen.intro.push(mode); };
  g.showBossPhase = function (e, label, line, full) { seen.phase.push({ label: label, line: line, full: full }); };
  g.showBossFinal = function (e, t) { seen.final.push(t); };
  try {
    // Entrée (B1, B2)
    var boss = forceBoss();
    ok(boss && boss.isBoss, "un boss d'aventure est en face (" + boss.name + ")");
    if (!seen.intro.length) BM.onEnemyShown(boss); // si l'affichage du spawn n'est pas passé par renderEnemy
    ok(seen.intro[0] === "full", "B2 : première rencontre -> carte d'entrée complète (" + seen.intro.join(",") + ")");
    ok(BM.onEnemyShown(boss) === null && seen.intro.length === 1, "B2 : une seule fois par rencontre");

    // Phase (B3 option A) : le vrai moteur appelle le crochet
    boss.phases = [{ atPct: 0.5, label: "entre en rage" }];
    boss.hp = Math.floor(boss.maxHp * 0.4);
    g.CombatEngine.checkPhases(boss);
    ok(seen.phase.length === 1 && seen.phase[0].label === "entre en rage" && seen.phase[0].full === true, "B3 : checkPhases -> bandeau de phase (flash à la première)");

    // Coup fatal (B4, B5) : le vrai moteur appelle le crochet
    var key = BM.keyOf(boss);
    run("game.enemy.hp = 1; game.enemy.maxHp = 1; CombatEngine.killEnemy();");
    var t = g.game.bossTrophies[key];
    ok(t && t.name === BM.cleanName(boss) && t.level >= 1 && typeof t.at === "number", "B5 : première victoire -> trophée (nom, date, niveau)");
    ok(seen.final.length === 1 && seen.final[0] === t, "B4 : coup final mis en scène à la première victoire");

    // Rejoué : bandeau court, pas de trophée neuf
    var n0 = seen.intro.length;
    var boss2 = forceBoss();
    if (seen.intro.length === n0) BM.onEnemyShown(boss2);
    ok(BM.keyOf(boss2) !== key || seen.intro[seen.intro.length - 1] === "short", "B1 : même boss rejoué -> bandeau court");
    var before = Object.keys(g.game.bossTrophies).length;
    if (BM.keyOf(boss2) === key) {
      run("game.enemy.hp = 1; game.enemy.maxHp = 1; CombatEngine.killEnemy();");
      ok(Object.keys(g.game.bossTrophies).length === before && seen.final.length === 1, "B1 : pas de second trophée, pas de coup final rejoué");
    }

    // Mises en scène coupées : rien d'affiché, le trophée est quand même gagné
    g.Prefs.set("bossMoments", false);
    var e3 = { id: "orcwarlord", name: "Seigneur de guerre orc", isBoss: true };
    ok(BM.onEnemyShown(e3) === null && BM.isFullMoment(e3) === false, "B4 : réglage coupé -> pas de carte d'entrée");
    var tr3 = BM.onBossKilled(e3);
    ok(tr3 && seen.final.length === 1, "B4 : réglage coupé -> trophée gagné sans mise en scène");
    g.Prefs.set("bossMoments", true);

    // Un ennemi ordinaire n'est pas un moment
    ok(BM.onEnemyShown({ id: "wolf", name: "Loup", isBoss: false }) === null && BM.onBossKilled({ id: "wolf", isBoss: false }) === null, "B1 : un ennemi ordinaire ne déclenche rien");

    // v3.350.0 : élite posée AVANT l'arrivée sur l'écran de combat (carte vivante, quête qui
    // commence par son boss) -> la carte d'entrée s'ouvre à l'arrivée sur l'onglet Combat.
    (function () {
      var unl = g.isTabUnlocked, ctx = g.hasCombatQuestContext, n0 = seen.intro.length;
      g.isTabUnlocked = function () { return true; };
      g.hasCombatQuestContext = function () { return true; };
      try {
        g.game.activeTab = "village";
        var el = g.EliteManager.spawn("arbre_mere", "forest", 0);
        ok(el && !el._momentShown && seen.intro.length === n0, "v3.350.0 : élite posée hors de l'écran de combat -> pas encore de carte d'entrée");
        g.switchTab("combat");
        ok(el._momentShown === true && seen.intro.length === n0 + 1, "v3.350.0 : arrivée sur l'écran de combat -> carte d'entrée");
        g.switchTab("combat");
        ok(seen.intro.length === n0 + 1, "v3.350.0 : une seule fois, même si l'onglet est rouvert");
      } finally { g.isTabUnlocked = unl; g.hasCombatQuestContext = ctx; g.game.activeTab = "combat"; }
    })();
  } finally { g.showBossIntro = sI; g.showBossPhase = sP; g.showBossFinal = sF; }

  // Persistance : les quatre points
  var saved = g.buildSaveData();
  ok(saved.bossTrophies && Object.keys(saved.bossTrophies).length >= 2, "sauvegarde : trophées écrits");
  var rest = BM.restore({ "x:Y": { name: "Y", at: 5, level: 3, rounds: 9, allies: ["Wenna", 4], worldId: "forest" }, bad: 12, "z:Z": { at: 1 } });
  ok(Object.keys(rest).length === 1 && rest["x:Y"].allies.length === 1, "chargement : entrées mal formées écartées");
  BM.restore(saved.bossTrophies);
  run("fullResetState();");
  ok(Object.keys(g.game.bossTrophies).length === 0, "réinitialisation complète : plus de trophée");
  ok(g.createInitialGameState().bossTrophies && typeof g.createInitialGameState().bossTrophies === "object", "état initial : bossTrophies présent (changement de héros)");

  // Pause du combat : la racine utilisée est bien dans les modales bloquantes
  var loop = require("fs").readFileSync(ROOT + "/js/main/game-loop.js", "utf8");
  var view = require("fs").readFileSync(ROOT + "/js/ui/boss-moment-view.js", "utf8");
  ok(loop.indexOf('"cycle-modal-root"') !== -1 && view.indexOf('getElementById("cycle-modal-root")') !== -1, "B4 : carte d'entrée et coup final mettent le combat en pause (racine bloquante)");

  // Bestiaire
  g.game.bossTrophies = { "orcwarlord:Seigneur de guerre orc": { name: "Seigneur de guerre orc", at: Date.now(), level: 7, rounds: 14, allies: ["Wenna"] } };
  g.bestiaryTrophiesOpen = true;
  var bh = g.buildBestiaryTrophiesHTML();
  ok(bh.indexOf("Trophées") !== -1 && bh.indexOf("14 rounds") !== -1 && bh.indexOf("avec Wenna") !== -1, "B5 : les trophées au Bestiaire (rounds, compagnons)");
  g.game.bossTrophies = {};
  ok(g.buildBestiaryTrophiesHTML() === "", "B5 : rien au Bestiaire tant qu'aucun trophée");
})();


/* [129] v3.334.0 — Patrouilles de compagnons (P-0, P-1), conception Évolutions v1.0. */
console.log("\n[129] v3.334.0 — Patrouilles : départ, groupe, retour, rappel, butin, persistance");
(function () {
  run("fullResetState(); game.playerName='P'; game.heroId='knight'; VillageBuildingManager.ensure(); EquipmentManager.recalcStats(); game.heroHp = game.heroMaxHp; game.activeTab = 'campement';");
  var PM = g.PatrolManager, CM = g.CompanionManager;
  ok(PM.isUnlocked() === false, "P9 : pas de patrouille sans compagnon");
  CM.unlock("wenna");
  ok(PM.isUnlocked() === true && CM.partyIds().indexOf("wenna") !== -1, "P9 : Wenna arrive -> patrouilles ouvertes, elle est dans le groupe");

  // Destinations : secteurs libérés du monde courant
  var libSave = g.LivingMapManager.isLiberated;
  g.LivingMapManager.isLiberated = function (m, s) { return m === "forest" && (s === "gue" || s === "menhirs"); };
  try {
    var dests = PM.getDestinations();
    ok(dests.length === 2 && dests[0].main === "bois" && dests[1].main === "pierre", "P4 : deux secteurs libérés, ressource dominante de chacun");

    // Rendement égal par heure (P3), anneau et améliorations
    var e2 = PM.estimate("wenna", "forest", "gue", 2), e8 = PM.estimate("wenna", "forest", "gue", 8);
    ok(Math.abs(e8.loot.bois - 4 * e2.loot.bois) <= 4 && Math.abs(e8.gold - 4 * e2.gold) <= 4, "P3 : 8 h rapporte 4 fois 2 h (rendement égal par heure)");
    var eRing2 = PM.estimate("wenna", "forest", "menhirs", 8);
    ok(eRing2.loot.pierre > e8.loot.bois * 0.99, "P4 : un secteur de l'anneau 2 rapporte un peu plus (×1,15)");
    CM.state("wenna").upgrades = 4;
    var eUp = PM.estimate("wenna", "forest", "gue", 8);
    ok(Math.abs(eUp.loot.bois / e8.loot.bois - 1.2) < 0.02, "P8 : +5 % par amélioration (4 -> +20 %)");
    CM.state("wenna").upgrades = 0;

    // Départ : le compagnon quitte le groupe (P2), butin tiré au départ
    var seq = [0.5, 0.99, 0.99, 0.2, 0.5];
    var i = 0;
    ok(PM.start("wenna", "gue", 8, function () { return seq[(i++) % seq.length]; }) === true, "départ : 8 h au Pont du gué");
    var p = PM.get("wenna");
    ok(p && p.endsAt - p.startedAt === 8 * 3600e3 && p.loot.bois > 0 && p.gold > 0, "butin tiré au départ, retour dans 8 h");
    ok(CM.partyIds().indexOf("wenna") === -1, "P2 : en patrouille, Wenna n'est plus dans le groupe de combat");
    var card = g.buildCompanionCardHTML("wenna");
    ok(card.indexOf("cp-patrol-note") !== -1 && card.indexOf(">Avec toi</button>") === -1, "P2 : sa fiche dit « En patrouille » au lieu du choix Avec toi / Au camp");
    ok(PM.start("wenna", "gue", 2) === false, "une seule patrouille à la fois par compagnon");
    ok(PM.getReturned().length === 0, "pas encore rentrée");
    ok(g.FilRouge.all().every(function (a) { return a.id !== "patrol"; }), "fil rouge : rien tant qu'elle marche");

    // Retour (horloge murale)
    p.endsAt = Date.now() - 1000;
    var back = PM.getReturned();
    ok(back.length === 1 && back[0].companionName === "Wenna" && back[0].feminine === true && back[0].sectorName === "Pont du gué", "retour : Wenna est rentrée du Pont du gué");
    ok(g.FilRouge.all().some(function (a) { return a.id === "patrol" && a.urgent; }), "fil rouge : patrouille rentrée, marquée urgente");
    var s = g.ReturnManager.complete({ produced: {}, crafted: {}, ms: 8 * 3600e3 }, g.ReturnManager.capture());
    ok(s.patrolsBack === 1 && g.ReturnManager.hasContent(s), "écran de retour : une patrouille rentrée suffit à l'ouvrir");

    var bois0 = Number(g.game.resources.bois || 0), gold0 = Number(g.game.gold || 0);
    var wantBois = p.loot.bois, wantGold = p.gold;
    var res = PM.collect("wenna");
    ok(res && g.game.resources.bois === bois0 + wantBois && g.game.gold === gold0 + wantGold, "butin crédité : +" + wantBois + " bois, +" + wantGold + " or");
    ok(typeof res.story === "string" && res.story.indexOf("Pont du gué") !== -1, "P6 : un récit, qui nomme le secteur");
    ok(!PM.isOnPatrol("wenna") && CM.partyIds().indexOf("wenna") !== -1, "P2 : revenue, elle rejoint le groupe");

    // Plafond de l'Entrepôt (E1) : ce qui dépasse est perdu, et dit
    PM.start("wenna", "gue", 2);
    var p2 = PM.get("wenna"); p2.loot = { bois: 100 }; p2.gold = 0; p2.endsAt = Date.now() - 1;
    g.game.resources.bois = g.WarehouseManager.getCap("bois") - 30;
    var r2 = PM.collect("wenna");
    ok(r2.loot.bois === 30 && r2.lost.bois === 70, "E1 : Entrepôt presque plein -> 30 entrent, 70 perdus (affichés)");

    // Rappel au prorata (P2)
    g.game.resources.bois = 0;
    PM.start("wenna", "gue", 8);
    var p3 = PM.get("wenna"); p3.loot = { bois: 400 }; p3.ration = { viande: 10 }; p3.gold = 100;
    p3.startedAt = Date.now() - 2 * 3600e3; p3.endsAt = p3.startedAt + 8 * 3600e3;
    var r3 = PM.recall("wenna");
    ok(r3.recalled && Math.abs(r3.loot.bois - 100) <= 1 && Math.abs(r3.gold - 25) <= 1 && !r3.loot.viande && !r3.story, "P2 : rappel après 2 h sur 8 -> un quart du butin, sans ration ni récit");

    // Tirage : ingrédients de rations rares, récit rare plus probable sur 8 h
    var withRation = 0, rare8 = 0, rare2 = 0, N = 400;
    for (var k = 0; k < N; k++) {
      var t8 = PM.roll("wenna", "forest", "gue", 8), t2 = PM.roll("wenna", "forest", "gue", 2);
      if (t8.ration.viande) withRation++; // v3.485.0 : ingrédients de rations à part du butin
      if (t8.story.rare) rare8++;
      if (t2.story.rare) rare2++;
    }
    ok(withRation > N * 0.12 && withRation < N * 0.38, "P5 : ingrédients de rations sur ~24 % des patrouilles de 8 h (" + withRation + "/" + N + ")");
    ok(rare8 > rare2 * 2, "P6 : récit rare bien plus probable sur 8 h (" + rare8 + " contre " + rare2 + ")");

    // Aucun échec (P7), sécurité
    ok(PM.start("wenna", "etang", 8) === false, "P4 : secteur non libéré -> refusé");
    g.game.activeTab = "combat";
    ok(PM.canStart("wenna") === "Pas pendant un combat", "pas de départ en plein combat");
    g.game.activeTab = "campement";
    ok(PM.start("wenna", "gue", 5) === false, "durée hors 2/4/8 -> refusée");
  } finally { g.LivingMapManager.isLiberated = libSave; }

  // Persistance : les quatre points
  g.LivingMapManager.isLiberated = function () { return true; };
  try { PM.start("wenna", "gue", 4); } finally { g.LivingMapManager.isLiberated = libSave; }
  var saved = g.buildSaveData();
  ok(saved.patrols && saved.patrols.wenna && saved.patrols.wenna.sectorId === "gue", "sauvegarde : patrouille en cours écrite");
  var rest = PM.restore({ wenna: saved.patrols.wenna, inconnu: saved.patrols.wenna, maddoc: { sectorId: 3 } });
  ok(Object.keys(rest).length === 1 && rest.wenna.loot.bois > 0, "chargement : compagnon inconnu ou entrée mal formée écartés");
  run("fullResetState();");
  ok(Object.keys(g.game.patrols).length === 0, "réinitialisation complète : plus de patrouille");
  ok(g.createInitialGameState().patrols && typeof g.createInitialGameState().patrols === "object", "état initial : patrols présent (changement de héros)");

  // Données : chaque secteur des deux cartes a ses ressources, chaque récit est rempli
  var okSect = true;
  ["forest", "desert"].forEach(function (m) {
    g.LIVING_MAPS[m].sectors.forEach(function (sec) { var r = g.PATROL_SECTORS[m][sec.id]; if (!r || !g.WAREHOUSE_RESOURCES[r[0]] || !g.WAREHOUSE_RESOURCES[r[1]]) okSect = false; });
  });
  ok(okSect, "P4 : chaque secteur de la Forêt et du Désert a deux ressources valides");
  var okStory = ["wenna", "maddoc"].every(function (c) { return ["forest", "desert"].every(function (m) { var s = g.PATROL_STORIES[c][m]; return s.common.length === 3 && s.rare.length === 1; }); });
  ok(okStory, "P6 : 3 récits communs + 1 rare par compagnon et par monde");
  ok(g.GENERIC_TUTORIALS.patrols_intro && g.GENERIC_TUTORIALS.patrols_intro.tab === "more", "P9 : fiche au catalogue de tutoriels");
})();


/* [134] v3.351.0 — Le chargement ne sauvegarde plus (trouvé par tools/harness/parcours-harness.js, P2). */
console.log("\n[134] v3.351.0 — loadGame() d'un héros à compagnon : aucune sauvegarde, absence intacte");
(function () {
  var game = freshCombat("ranger");
  g.game.saveSupported = true;
  g.CompanionManager.unlock("wenna");
  g.CompanionManager.setSetting("wenna", "healThreshold", g.COMPANION_HEAL_THRESHOLDS ? g.COMPANION_HEAL_THRESHOLDS[0].value : 0.6);
  g.saveGame();
  var key = g.getActiveSaveKey(), d = JSON.parse(g.localStorage.getItem(key));
  d.lastOnline = d.savedAt = Date.now() - 9 * 3600e3;          // 9 h d'absence
  g.localStorage.setItem(key, JSON.stringify(d));
  var n = 0, SG = g.saveGame;
  g.saveGame = function () { n++; return SG.apply(this, arguments); };
  var charge;
  try { charge = g.loadGame(); } finally { g.saveGame = SG; }
  ok(charge === true, "la sauvegarde se recharge");
  ok(n === 0, "loadGame() ne sauvegarde pas en cours de chargement (" + n + " écriture(s))");
  ok(Math.round((Date.now() - g.game.lastOnline) / 3600e3) === 9, "l'absence reste lisible après le chargement (9 h), l'écran de retour peut la voir");
  ok(g.CompanionManager.state("wenna").unlocked === true, "les réglages du compagnon sont relus");
})();

/* [135] v3.355.0 — Lot 1 des corrections de la campagne B (D3, D5, D6, ateliers). */
console.log("\n[135] v3.355.0 — Portrait propre, conseil du compagnon, place du jour rendue, ateliers");
(function () {
  /* D3 : l'image propre de l'ennemi passe avant la fiche de base (Basilic sur base slimeking) */
  var basilic = { id: "slimeking", isBoss: true, image: "./images/Boss/basilic.webp" };
  ok(g.getEnemyPortrait(basilic) === "./images/Boss/basilic.webp", "rangée de groupe : le Basilic garde son portrait (" + g.getEnemyPortrait(basilic) + ")");
  ok(g.getEnemyPortrait({ id: "slimeking", isBoss: true }) === g.BOSS_DB.slimeking.image, "sans image propre : repli sur la fiche de base");
  var src = require("fs").readFileSync(ROOT + "/js/ui/combat-screen-view.js", "utf8");
  ok(/function enemyImage\(e\) \{\s*if \(typeof getEnemyPortrait === "function"\) return getEnemyPortrait\(e\);/.test(src), "écran de combat : image propre d'abord (getEnemyPortrait)");
  var d1 = g.DUNGEONS.filter(function (d) { return d.id === 1; })[0];
  ok(d1 && d1.boss.image === "./images/Boss/basilic.webp", "le boss du Donjon I porte basilic.jpg");

  /* D5 : en Tactique, le bouton conseillé du compagnon est marqué ; en Grimoire, rien */
  var game = freshCombat("knight");
  g.CompanionManager.unlock("wenna");
  g.CombatEngine.spawnEnemy();
  var w = (game.combat.allies || []).filter(function (a) { return a && a.companionId === "wenna"; })[0];
  ok(!!w, "Wenna est dans le groupe");
  game.combatMode = "tactique";
  // v3.459.7 (audit O13) : la compétence du compagnon est conseillée quand sa politique la choisit
  w.cooldown = 0; w.charges = 3;
  run("game.heroHp = Math.floor(game.heroMaxHp * 0.30);");
  var h2 = g.cbxCompanionActionsHTML(w);
  ok(g.CompanionManager.chooseAction(w) === "skill" && /cbx-skill is-suggested"\s+onclick="companionAction\('skill'/.test(h2), "héros blessé : Wenna conseille son soin");
  ok(h2.indexOf("Le Grimoire la conseille") !== -1, "le conseil porte sa mention, comme celui du héros");
  w.cooldown = 3;
  ok(g.cbxCompanionActionsHTML(w).indexOf("is-suggested") === -1, "soin en recharge : plus de conseil sur la compétence");
  game.combatMode = "grimoire";
  ok(g.buildCbxCmdHTML().indexOf("cbx-cskill") === -1, "Grimoire : aucune commande de compagnon, donc aucun conseil");
  game.combatMode = "tactique";

  /* D6 : un échec subi rend la place du jour, un abandon la garde */
  var S = g.SceneRunManager;
  S.ensureDefaults();
  var today = S._today();
  game.explorationProgression.petiteAventure = { spent: 3, since: Date.now() };
  var r1 = { paSlotDay: today, status: "gate" };
  S._refundPetiteAventureSlot(r1);
  ok(game.explorationProgression.petiteAventure.spent === 2 && r1.paSlotDay === null, "échec subi : la place est rendue (3 → 2)");
  S._refundPetiteAventureSlot(r1);
  ok(game.explorationProgression.petiteAventure.spent === 2, "rendue une seule fois");
  S._refundPetiteAventureSlot({ status: "gate" });
  ok(game.explorationProgression.petiteAventure.spent === 2, "une sortie qui n'a pas pris de place (hors cap) ne rend rien");
  // v3.391.0 : lu dans Pa2Run (l'ancien moteur est retiré).
  var prs = String(g.Pa2Run.abandon), pfull = require("fs").readFileSync(ROOT + "/js/systems/pa2-run.js", "utf8");
  ok(prs.indexOf("_refundPetiteAventureSlot") === -1 && pfull.indexOf("SceneRunManager._refundPetiteAventureSlot") !== -1, "abandon volontaire : place gardée ; échec subi : place rendue");

  /* Ateliers : débit et remboursement par l'Entrepôt */
  game = freshCombat("knight");
  game.explorationProgression.farmUnlocked = true;
  run("ProductionManager.unlockBuilding('farm');");
  g.WarehouseManager.addResource("ble", 50, true); g.WarehouseManager.addResource("eau", 20, true);
  var W = g.WarehouseManager, rm = 0, rf = 0, RM = W.removeResource, RF = W.refundResource;
  W.removeResource = function () { rm++; return RM.apply(this, arguments); };
  W.refundResource = function () { rf++; return RF.apply(this, arguments); };
  var MQ = g.WorkshopsSystem.getMaxQueueLength;
  g.WorkshopsSystem.getMaxQueueLength = function () { return 3; };   // deux lots en file : seul le second s'annule
  try {
    g.WorkshopsSystem.enqueueCraft("boulangerie", "pain", 1);
    g.WorkshopsSystem.enqueueCraft("boulangerie", "pain", 1);
    var avant = W.getAmount("ble");
    var q = g.WorkshopsSystem.getQueue("boulangerie");
    g.WorkshopsSystem.cancelCraft("boulangerie", q[1].id);
    ok(rm === 4, "la mise en file débite par WarehouseManager.removeResource (" + rm + ", 2 lots × 2 intrants)");
    ok(rf === 2 && W.getAmount("ble") === avant + 15, "l'annulation rembourse par WarehouseManager.refundResource (+15 blé, +5 eau)");
  } finally { W.removeResource = RM; W.refundResource = RF; g.WorkshopsSystem.getMaxQueueLength = MQ; }
  var wsrc = require("fs").readFileSync(ROOT + "/js/systems/workshops-system.js", "utf8");
  ok(!/game\.resources\[[^\]]+\]\s*=/.test(wsrc), "workshops-system.js n'écrit plus directement dans game.resources");

  /* Code mort retiré */
  ok(typeof g.WORLD_PANEL_BACKGROUNDS === "undefined", "WORLD_PANEL_BACKGROUNDS retiré");
  var html = require("fs").readFileSync(ROOT + "/index.html", "utf8");
  ok((html.match(/companion-system\.js/g) || []).length === 1, "companion-system.js chargé une seule fois");
  var sw = require("fs").readFileSync(ROOT + "/sw.js", "utf8");
  ok(sw.indexOf("js/main/utils.js") === -1, "sw.js ne précache plus js/main/utils.js (fichier à supprimer)");
})();

/* [136] v3.356.0 — Lot 2 des corrections de la campagne B (D1, D2, D4). */
console.log("\n[136] v3.356.0 — Arme de la Cité, Battue du Désert, palier de l'étape 13");
(function () {
  /* D4 : l'arme de la Cité, par classe, en récompense de desert_12 */
  var def = g.ELITE_UNIQUE_LOOT.arme_cite;
  ok(!!def && def.slot === "weapon" && def.rarity === "green" && def.stat === "tapDmg", "l'arme de la Cité est une arme Inhabituelle");
  ok(def.value >= 32 * 1.0 && def.value <= 45, "sa valeur reste dans la fourchette Inhabituelle du Désert (" + def.value + ")");
  var noms = { knight: "Lame de la Cité", ranger: "Arc de la Cité", mage: "Bâton de la Cité" };
  Object.keys(noms).forEach(function (hid) {
    var game = freshCombat(hid);
    var it = g.EliteManager.buildUniqueLoot("arme_cite");
    ok(it && it.name === noms[hid] && g.isWeaponIconAllowedForCurrentHero(it.icon), hid + " : « " + (it && it.name) + " », arme de sa classe");
  });
  ok(g.STORY_REWARDS.desert_12.uniqueLoot === "arme_cite", "récompense de desert_12");
  var game = freshCombat("mage");
  var avant = (game.inventory || []).length;
  var rows = g.StoryQuestManager._grantReward(g.STORY_REWARDS.desert_12);
  var recue = (game.inventory || []).filter(function (x) { return x.name === "Bâton de la Cité"; })[0];
  ok(!!recue && game.inventory.length === avant + 1, "réclamer desert_12 met l'arme au sac");
  ok(rows.some(function (r) { return r.value === "Bâton de la Cité"; }), "elle figure dans la carte de récompense");
  ok(recue && recue.affixes.length === 1 && recue.affixes[0] !== def.affixes[0], "son affixe est une copie, pas la donnée");
  // elle compte pour le palier de l'étape 13
  game.equipped = { weapon: recue };
  ok(g.storyPalierDesert(game).armeVerte === true, "elle compte comme l'arme Inhabituelle du palier");

  /* D2 : Battue du Désert */
  var B = g.HUNT_QUESTS.hq_desert_battue;
  ok(!!B && B.type === "gold" && B.worldId === "desert" && B.rewardGold === 450 && B.lotSize === 20, "Battue du Désert : 20 bêtes, 450 or");
  game = freshCombat("knight");
  run("VillageBuildingManager.ensure(); game.unlockedTabs.village = true;");
  var vue = function () { return g.MissionBoard._huntMissions().some(function (m) { return m.questId === "hq_desert_battue"; }); };
  game.explorationProgression.desertCrossingCompleted = false;
  ok(!vue(), "fermée avant l'arrivée au Désert");
  game.explorationProgression.desertCrossingCompleted = true;
  ok(vue(), "ouverte après desert_01");
  var e = g.QuestEnemyManager.spawnFor(B, false);
  var e1 = Array.isArray(e) ? e[0] : e;
  ok(e1 && ["scarab", "scorpion", "sandworm", "sandwarrior"].indexOf(e1.id) !== -1, "des bêtes des Dunes (" + (e1 && e1.id) + ")");
  var or0 = game.gold;
  run("HuntQuestManager.start('hq_desert_battue');");
  ok(game.huntRun.active && game.huntRun.questId === "hq_desert_battue", "elle se lance");
  run("game.huntRun.killsInLot = 19; HuntQuestManager.onEnemyKilled();");
  ok(game.gold - or0 >= 450 && !game.huntRun.active, "le lot bouclé verse la prime (+" + (game.gold - or0) + " or)");
  var req = g.ProvisionsManager.getRequirement("hunt", B);
  ok(req && req.resourceId === "ration", "la relancer demande une Ration moyenne, vivres du Désert, comme toute chasse refaite");
})();

