console.log("\n[143] v3.366.0 — Petites Aventures : réserve rechargeable ; Ensablement du seul secteur tenté");
(function () {
  var S = g.SceneRunManager, H = S.PETITE_AVENTURE_RECHARGE_MS;
  game = freshCombat("knight");
  S.ensureDefaults();
  /* Migration : l'ancien compteur du jour devient des places dépensées */
  game.explorationProgression.petiteAventure = { day: S._today(), count: 2 };
  ok(S.petiteAventureCountToday() === 2 && typeof game.explorationProgression.petiteAventure.since === "number" && !("day" in game.explorationProgression.petiteAventure), "ancienne forme (jour, compteur) migrée : 2 places dépensées, horloge lancée");
  game.explorationProgression.petiteAventure = { day: "Mon Jan 01 1999", count: 3 };
  ok(S.petiteAventureCountToday() === 0, "ancienne forme d'un autre jour : réserve pleine");

  /* Réserve de 3 (Forêt) : dépense, blocage, recharge une à une */
  var cap = S.getPetiteAventureCap();
  for (var i = 0; i < cap; i++) S._consumePetiteAventureSlot();
  ok(cap === 3 && !S.canStartPetiteAventureToday() && S.petiteAventureNextInMs() > H - 60000, "Forêt : 3 places, réserve vide, prochaine dans ~4 h");
  ok(/^Prochaine expédition dans (4 h|3 h 59)$/.test(S.petiteAventureWaitLabel()), "libellé : « " + S.petiteAventureWaitLabel() + " »");
  game.explorationProgression.petiteAventure.since -= H + 1000;
  ok(S.petiteAventureCountToday() === 2 && S.canStartPetiteAventureToday(), "4 h plus tard : une place revenue, une seule");
  game.explorationProgression.petiteAventure.since -= 2 * H;
  ok(S.petiteAventureCountToday() === 0 && game.explorationProgression.petiteAventure.since === null, "8 h de plus : réserve pleine, l'horloge s'arrête");
  game.explorationProgression.petiteAventure.since = null;
  S._consumePetiteAventureSlot();
  ok(Math.abs(game.explorationProgression.petiteAventure.since - Date.now()) < 5000, "réserve pleine : l'horloge part avec la première place dépensée");

  /* Désert : réserve de 4 ; une nuit de 8 h en rend 2 */
  game.worldsEverReached = { 0: true, 1: true };
  ok(S.getPetiteAventureCap() === 4, "Désert : réserve de 4");
  game.explorationProgression.petiteAventure = { spent: 4, since: Date.now() - 8 * 3600e3 - 1000 };
  ok(S.petiteAventureCountToday() === 2, "une nuit de 8 h rend 2 places");
  ok(g.formatPetiteAventureWait === undefined && S.formatPetiteAventureWait(45 * 60000) === "45 min" && S.formatPetiteAventureWait(133 * 60000) === "2 h 13", "format d'attente : 45 min, 2 h 13");

  /* Admin : bonus négatif toujours possible, « Remplir la réserve » */
  game.explorationProgression.petiteAventure = { spent: -2, since: null };
  ok(S.canStartPetiteAventureToday() && S.petiteAventureCountToday() === -2, "Admin : places en plus (compteur négatif) respectées");

  /* Ensablement : jamais plus loin que le secteur tenté */
  var LM = g.LivingMapManager;
  LM.ensureDefaults();
  var src = require("fs").readFileSync(ROOT + "/js/systems/living-map-system.js", "utf8");
  var body = src.slice(src.indexOf("  onRunEnd: function"), src.indexOf("  getBrakeChance: function"));
  ok(body.indexOf("this.pickRegression(") === -1 && body.indexOf("this.regress(mapId, sectorId") !== -1, "onRunEnd ne reprend plus que le secteur tenté");
})();

console.log("\n[144] v3.368.0 — Socle multilangue : _t, _tn, repli sur le français, langue en préférence d'appareil");
(function () {
  var I = g.I18n, P = g.Prefs;
  ok(typeof g._t === "function" && typeof g._tn === "function" && I && typeof P.getValue === "function", "_t, _tn, I18n et Prefs.getValue existent");
  /* Français (défaut) : le texte est rendu tel quel, gabarits remplis */
  I._lang = null; delete P._load().lang;
  ok(I.lang() === "fr" && P.getValue("lang") === "fr", "langue par défaut : français, sans rien dans les préférences");
  ok(g._t("Santé du héros") === "Santé du héros", "français : le texte est sa propre traduction");
  ok(g._t("Prochaine expédition dans {d}", { d: "2 h 13" }) === "Prochaine expédition dans 2 h 13", "gabarit rempli");
  ok(g._t("Il reste {x}", {}) === "Il reste {x}", "paramètre absent : {x} reste visible (repérable au test)");
  ok(g._tn(1, "{n} place", "{n} places") === "1 place" && g._tn(0, "{n} place", "{n} places") === "0 place" && g._tn(3, "{n} place", "{n} places") === "3 places", "pluriel français : 0 et 1 au singulier");
  /* Anglais : dictionnaire, contexte, repli */
  I.register("en", { "Partir": "Leave", "quête|Partir": "Set out", "Il reste {n} or": "{n} gold left", "{n} place||{n} places": ["{n} slot", "{n} slots"] });
  I._lang = "en";
  ok(g._t("Partir") === "Leave" && g._t("Partir", "quête") === "Set out", "anglais : texte seul et texte en contexte");
  ok(g._t("Partir", "inconnu") === "Leave", "contexte absent du dictionnaire : repli sur le texte seul");
  ok(g._t("Jamais traduit") === "Jamais traduit", "traduction absente : le français s'affiche, jamais une clé");
  ok(g._t("Il reste {n} or", { n: 5 }) === "5 gold left", "gabarit traduit puis rempli");
  ok(g._tn(0, "{n} place", "{n} places") === "0 slots" && g._tn(1, "{n} place", "{n} places") === "1 slot", "pluriel anglais : 0 au pluriel, 1 au singulier");
  ok(g._t("onglet|Quêtes".split("|")[1], "onglet") === "Quests", "js/lang/en.js chargé : l'onglet « Quêtes » devient « Quests »");
  /* Pseudo-langue */
  I._lang = "xx";
  ok(g._t("Camp") === "⟦Camp⟧" && g._tn(2, "{n} place", "{n} places") === "⟦2 places⟧", "pseudo-langue : tout texte extrait entre ⟦ ⟧");
  /* Préférence d'appareil, hors sauvegarde */
  P.setValue("lang", "en"); I._lang = null;
  ok(I.lang() === "en" && JSON.parse(g.localStorage.getItem("aethervale_prefs")).lang === "en", "la langue est lue dans aethervale_prefs");
  P.setValue("lang", "klingon"); I._lang = null;
  ok(I.lang() === "fr", "langue inconnue : retour au français");
  ok(JSON.stringify(g.buildSaveData()).indexOf('"lang"') === -1, "la langue n'entre pas dans la sauvegarde");
  ok(P.get("filRouge") === true, "les interrupteurs de Prefs ne bougent pas");
  ok(I.setLang("klingon") === false, "setLang refuse une langue inconnue");
  /* Remise en état pour la suite */
  delete P._load().lang; P._save(P._load()); I._lang = null; delete I.dicts.en["Partir"]; delete I.dicts.en["quête|Partir"]; delete I.dicts.en["Il reste {n} or"]; delete I.dicts.en["{n} place||{n} places"];
  ok(I.lang() === "fr", "remis en français");
})();

