console.log("\n[222] v3.447.0 — Initiative : jet, ordre, file de tours, Garde, cadence du jeu réel");
(function () {
  var I = g.Initiative, CE = g.CombatEngine, savedCtx = g.hasCombatQuestContext;
  /* Ordre forcé : total de chacun posé à la main sur le combat en cours. */
  function force(list) { list.forEach(function (p) { p[0]._ini = { key: I.combatKey, r1: p[1], r2: 0, bonus: 0, total: p[1] }; }); }
  function calme(e) { e.engageIn = 0; e.chargeIn = e.shieldIn = e.silenceIn = e.healIn = 99; e.hp = e.maxHp = 100000; }
  try {
    I.legacy = false;
    ok(I.bonusFromCelerity(0) === 0 && I.bonusFromCelerity(60) === 5 && I.bonusFromCelerity(5000) <= 10, "bonus = 10 × c / (c + 60) : 0 → +0, 60 → +5, jamais plus de +10");
    game = freshCombat("knight"); giveWeapon();
    var hero = g.CombatActors.heroActor(), tot = CE.getTotalCelerity();
    g.WorldManager.worldIndex = 5;
    ok(Math.abs(I.celerityOf(hero) - tot / 18) < 1e-9, "héros : célérité ramenée au monde (Tour ÷ 18)");
    g.WorldManager.worldIndex = 0;
    ok(I.hasAdvantage(hero) === false && !!I.rollOf(hero), "Chevalier : un dé, jet posé à l'ouverture du combat");
    game = freshCombat("ranger");
    hero = g.CombatActors.heroActor();
    ok(I.hasAdvantage(hero) && I.rollOf(hero).r2 > 0 && I.rollOf(hero).total === Math.max(I.rollOf(hero).r1, I.rollOf(hero).r2) + I.rollOf(hero).bonus, "Rôdeur : deux dés, le meilleur compte");

    // Égalité : ton camp d'abord ; sinon le plus haut total
    game = freshCombat("knight"); giveWeapon();
    hero = g.CombatActors.heroActor(); var e = game.enemy; calme(e);
    force([[hero, 10], [e, 10]]);
    ok(I.order()[0] === hero, "égalité : le héros passe devant l'ennemi");
    force([[hero, 5], [e, 15]]);
    ok(I.order()[0] === e && I.enemyBeforeHero(), "ennemi plus haut : il joue avant le héros");

    // Synchrone : l'ennemi frappe AVANT l'action du héros, même si cette action le tue
    e.hp = 1;
    var pv = game.heroHp;
    CE.heroAction("basic");
    ok(game.heroHp < pv, "l'ennemi joue d'abord : il frappe avant de tomber sous le coup du héros");

    // La Garde tient jusqu'au coup suivant de l'ennemi qui joue avant
    game = freshCombat("knight"); giveWeapon(); fillResource();
    hero = g.CombatActors.heroActor(); e = game.enemy; calme(e);
    force([[hero, 5], [e, 15]]);
    var gardes = [], strike = CE.enemyStrike;
    CE.enemyStrike = function () { gardes.push(!!game.classActiveDefense); return strike.apply(this, arguments); };
    var garde = CE.heroAction("defense");
    var apres = !!game.classActiveDefense;
    CE.heroAction("basic");
    CE.enemyStrike = strike;
    ok(garde && apres && gardes[1] === true, "Garde posée après le coup du loup : elle couvre son coup du round suivant");
    ok(!game.classActiveDefense, "et s'éteint au tour suivant du héros");

    // Contre : l'annonce tombe pendant le tour de l'ennemi, le héros la contre avant l'impact
    game = freshCombat("knight"); giveWeapon(); fillResource();
    hero = g.CombatActors.heroActor(); e = game.enemy; calme(e); e.chargeIn = 1;
    force([[hero, 5], [e, 15]]);
    CE.heroAction("basic");
    ok(e.chargeTelegraphed === true, "le loup annonce sa charge à son tour");
    var counter = (g.getClassSkills(g.ClassCombatManager.getCurrentClassId()) || {}).actions || {};
    var slot = Object.keys(counter).filter(function (k) { return (g.getAllGrimoireCounterIds(counter[k]) || []).indexOf("chargeIncoming") !== -1; })[0];
    pv = game.heroHp;
    if (slot) { CE.heroAction(slot); ok(e.chargeTelegraphed === false, "le héros la contre à son tour, avant l'impact (" + slot + ")"); }

    // Renfort : il lance son dé à son arrivée
    var nouveau = g.CombatEngine.prepareEnemy(g.WorldManager.generateEnemy());
    g.CombatActors.setEnemies(g.CombatActors.enemies().concat([nouveau]));
    ok(I.order().indexOf(nouveau) !== -1 && !!I.rollOf(nouveau), "un renfort lance son dé et entre dans l'ordre");

    // Jeu réel : un combattant toutes les 0,4 s, arrêt au tour du héros (Tactique)
    game = freshCombat("knight"); giveWeapon();
    hero = g.CombatActors.heroActor(); e = game.enemy; calme(e);
    force([[hero, 5], [e, 15]]);
    CE.paced = true; g.hasCombatQuestContext = function () { return true; };
    pv = game.heroHp;
    ok(CE.isHeroTurnAvailable() === false, "jeu réel : avant le tour du héros, ses boutons attendent");
    CE.tickRoundClock(0.5);
    ok(game.heroHp === pv, "ouverture du combat : le temps de voir les dés (1 s)");
    CE.tickRoundClock(0.5);
    ok(game.heroHp < pv && CE.isHeroTurnAvailable() === true, "le loup joue, puis le combat s'arrête au tour du héros");
    var r = game.combatRound.number;
    CE.tickRoundClock(2);
    ok(CE.isHeroTurnAvailable() === true && game.combatRound.number === r, "Tactique : le combat attend le choix du joueur");
    ok(CE.heroAction("basic") === true && CE._manualRoundOpen === true, "le héros joue ; la fin du round viendra au pas suivant");
    CE.tickRoundClock(0.4);
    ok(CE._manualRoundOpen === false, "pas suivant : le round se ferme");
    CE.tickRoundClock(0.4);
    ok(game.combatRound.number === r + 1, "et le suivant s'ouvre au pas d'après");
  } catch (err) {
    ok(false, "[222] exception : " + err.message + " " + (err.stack || "").split("\n")[1]);
  } finally {
    CE.paced = false; I.legacy = true; g.hasCombatQuestContext = savedCtx; g.WorldManager.worldIndex = 0;
  }
})();

console.log("\n[223] v3.448.0 — Camp : le feu et les rations soignent aussi les compagnons");
(function () {
  try {
    game = freshCombat("knight");
    var C = g.CompanionManager, K = g.CampManager;
    C.unlock("wenna");
    var mw = C.maxHpOf("wenna");
    run("game.activeTab = 'campement'; CombatActors.clearEnemies();");
    game.heroHp = game.heroMaxHp; C.state("wenna").hp = Math.floor(mw * 0.1);
    ok(K.teamFull() === false, "héros plein, Wenna blessée : l'équipe n'est pas pleine");
    game.campRegenLastAt = Date.now() - 60000;
    K.applyRegen(false);
    ok(C.hpOf("wenna") > Math.floor(mw * 0.1), "le feu de camp soigne Wenna même quand le héros est plein");
    run("WarehouseManager.addResource('ration', 3, true);");
    var def = g.WAREHOUSE_RESOURCES.ration;
    game.heroHp = Math.floor(game.heroMaxHp * 0.1); C.state("wenna").hp = Math.floor(mw * 0.2);
    var h0 = game.heroHp, w0 = C.hpOf("wenna");
    ok(K.eatRation("ration") === true, "une ration se mange");
    ok(game.heroHp - h0 === Math.floor(game.heroMaxHp * def.healPct) && C.hpOf("wenna") - w0 === Math.floor(mw * def.healPct),
      "une ration soigne le héros ET Wenna du même pourcentage");
    game.heroHp = game.heroMaxHp; C.state("wenna").hp = Math.floor(mw * 0.5);
    ok(K.eatRation("ration") === true, "héros plein : la ration sert encore, pour Wenna");
    C.state("wenna").hp = mw;
    ok(K.eatRation("ration") === false, "tout le monde plein : la ration reste au stock");
    var html = g.buildCampHTML();
    ok(html.indexOf("camp-comp-hp-wenna") !== -1, "la carte du camp montre la jauge de Wenna");
  } catch (err) {
    ok(false, "[223] exception : " + err.message + " " + (err.stack || "").split("\n")[1]);
  }
})();

/* [224] v3.448.1 — précache complet : tout script et toute feuille chargés par index.html doivent être
   précachés par sw.js, sinon le jeu casse hors-ligne après une mise à jour (58 fichiers oubliés avant). */
console.log("\n[224] v3.448.1 — Précache : index.html et sw.js concordent");
(function () {
  var html = fs.readFileSync(path.join(ROOT, "index.html"), "utf8");
  var sw = fs.readFileSync(path.join(ROOT, "sw.js"), "utf8");
  var re = /(?:src|href)="(?:\.\/)?((?:js|css)\/[^"?#]+)"/g, m, absents = [], n = 0;
  while ((m = re.exec(html))) { n++; if (sw.indexOf('"./' + m[1] + '"') === -1) absents.push(m[1]); }
  ok(n > 200, "index.html charge " + n + " scripts et feuilles");
  ok(absents.length === 0, "tous sont précachés" + (absents.length ? " — absents : " + absents.join(", ") : ""));
  var pre = sw.match(/"\.\/((?:js|css)\/[^"]+)"/g) || [], fantomes = [];
  pre.forEach(function (q) { var f = q.slice(3, -1); if (!fs.existsSync(path.join(ROOT, f))) fantomes.push(f); });
  ok(fantomes.length === 0, "aucun fichier précaché n'est absent du disque" + (fantomes.length ? " — " + fantomes.join(", ") : ""));
})();

/* [225] v3.448.1 — une sauvegarde illisible n'est plus écrasée : copie saine rechargée, version
   illisible gardée à part, écriture bloquée si elle n'a pas pu être mise de côté. */
console.log("\n[225] v3.448.1 — Sauvegarde illisible : copie saine, mise de côté, verrou");
(function () {
  var key = run("getActiveSaveKey()"), avant = {};
  Object.keys(storage).forEach(function (k) { avant[k] = storage[k]; });
  var realSet = g.localStorage.setItem;
  try {
    run("game.gold = 4242; saveGame();");
    var sain = storage[key];
    ok(run("loadGame()") === true && storage[key + "_bak"] === sain, "un chargement réussi garde une copie saine (_bak)");

    run("game.gold = 9999; saveGame();");
    storage[key] = storage[key].slice(0, -1); // JSON tronqué d'un octet
    var abime = storage[key];
    ok(run("loadGame()") === true, "partie tronquée : le chargement se rabat sur la copie saine");
    ok(run("game.gold") === 4242, "l'or est celui de la copie saine (4242)");
    ok(storage[key + "_illisible"] === abime, "la version illisible est gardée à part (_illisible)");

    storage[key] = abime; storage[key + "_bak"] = "{rompu";
    ok(run("loadGame()") === false, "copie saine illisible aussi : chargement refusé");
    ok(run("game.gold") !== 4242 && run("!game.playerName"), "l'état repart de zéro, sans reste à moitié restauré");
    ok(run("saveLockedKey") === null && run("saveGame()") === true, "version mise de côté : la partie neuve peut s'écrire");

    storage[key] = abime; delete storage[key + "_bak"];
    g.localStorage.setItem = function (k, v) { if (/_illisible$/.test(k)) throw new Error("quota"); realSet(k, v); };
    ok(run("loadGame()") === false && run("saveLockedKey") === key, "mise de côté impossible : l'emplacement est verrouillé");
    ok(run("saveGame()") === false && storage[key] === abime, "et rien n'est écrit dessus");
    g.localStorage.setItem = realSet;

    var exp = run("buildMultiSaveExportPayload()");
    ok(exp.unreadable && typeof exp.unreadable[run("getActiveSlot()")] === "string", "l'export emporte la version illisible");

    run("saveLockedKey = null; game.gold = 1; saveGame(); loadGame();");
    ok(!!storage[key + "_bak"], "copie saine refaite");
    run("clearSaveData()");
    ok(!storage[key + "_bak"], "effacer la partie efface aussi sa copie saine");
  } catch (err) {
    ok(false, "[225] exception : " + err.message);
  } finally {
    g.localStorage.setItem = realSet;
    run("saveLockedKey = null;");
    Object.keys(storage).forEach(function (k) { delete storage[k]; });
    Object.keys(avant).forEach(function (k) { storage[k] = avant[k]; });
    if (storage[key]) run("resetGameToFreshState(); loadGame();");
  }
})();

/* [226] v3.448.2 — le Trône de sable (fin du chapitre II, déclaré sur l'aventure 0) ajuste ses ennemis
   au héros de FIN de Désert (heroRef), plus au héros de début de Désert : Nezzam passait à 0-15 %. */
console.log("\n[226] v3.448.2 — Trône de sable : référence de l'ajustement au héros (heroRef)");
(function () {
  var W = g.WorldManager, CF = g.CombatForecast, Q = g.ADVENTURE_QUESTS.aq_desert_trone;
  var dmg0 = CF.getHeroDamagePerRound, ehp0 = CF.getHeroEffectiveHp, gen0 = W.generateEnemy, vus = [];
  try {
    CF.getHeroDamagePerRound = function () { return 340; };   // héros du profil campagne
    CF.getHeroEffectiveHp = function () { return 1400; };
    W.generateEnemy = function () { vus.push(W.getHeroScale()); return gen0.apply(this, arguments); };
    ok(Q.heroRef === "joueurDesert2" && Q.adventureIndex === 0, "le Trône déclare heroRef joueurDesert2 (aventure 0)");
    var boss = g.QuestEnemyManager.spawnFor(Q, true);
    ok(boss && boss.id === "nezzam", "spawnFor donne Nezzam");
    ok(vus.length && vus[0].hp === 1, "PV de Nezzam : pas d'ajustement (340 < 371 × 1,15), ×" + (vus[0] && vus[0].hp.toFixed(2)));
    ok(W._heroRefKey === null, "la référence de quête est rendue après la génération");
    W.worldIndex = 1; W.adventureIndex = 0;
    ok(W.getHeroScale().hp > 1.1, "hors quête, l'aventure 0 garde sa référence (début de Désert)");
    ok(Q.enemyPowerMult === 6 && Q.bossPowerMult === 1.4, "calage v3.448.2 : rencontres ×6, Nezzam ×1,4");
  } catch (err) {
    ok(false, "[226] exception : " + err.message);
  } finally {
    CF.getHeroDamagePerRound = dmg0; CF.getHeroEffectiveHp = ehp0; W.generateEnemy = gen0;
    W._heroRefKey = null; W.worldIndex = 0; W.adventureIndex = 0;
  }
})();

