/* [229] v3.448.5 — lisibilité (atelier/lisibilite.html, validé par Seb) : contrastes 4,5:1 sur le parchemin,
   textes à 12 px, surface de toucher de 44 px. Garde-fou contre un retour en arrière. */
console.log("\n[229] v3.448.5 — Lisibilité : contrastes, textes à 12 px, zones de toucher");
(function () {
  function css(f) { return fs.readFileSync(path.join(ROOT, "css", f), "utf8"); }
  function hex(h) { h = h.replace("#", ""); return [0, 2, 4].map(function (i) { return parseInt(h.substr(i, 2), 16); }); }
  function lum(c) { var a = c.map(function (v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }); return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2]; }
  function ratio(a, b) { var x = lum(hex(a)), y = lum(hex(b)); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
  var tok = css("00-tokens.css"), lire = function (n) { var m = tok.match(new RegExp(n + ":\\s*(#[0-9a-fA-F]{6})")); return m ? m[1] : null; };
  [["--nb-ink-dim", "texte secondaire"], ["--nb-gold-deep", "or de texte"], ["--nb-green-text", "vert de texte"]].forEach(function (t) {
    var v = lire(t[0]);
    ok(v && ratio(v, "#f6ecd9") >= 4.5 && ratio(v, "#efe0c2") >= 4.5, t[1] + " (" + t[0] + " " + v + ") : 4,5:1 au moins sur les deux crèmes");
  });
  ok(/\.map-quest-reward-value \{\s*color: var\(--nb-gold-deep\)/.test(css("06-map.css")), "l'or de la carte n'utilise plus --nb-gold (1,7:1)");
  ok(/\.hud-gauge \.kgauge-text \{ font-size: 12px/.test(css("02-layout.css")), "PV et XP du haut à 12 px");
  var cb = css("03-combat-screen.css");
  ok(!/\.cbx-(turn-badge|lvl-badge|cost-badge)[^}]*font-size: 10px/.test(cb) && !/cbx-cd-count \{ font-size: 10px/.test(cb), "badges de combat : plus de texte à 10 px");
  ok(/\.cbx-card:not\(\.is-hero\) \.cbx-card-nm \{ grid-column: 1 \/ -1; \}/.test(cb), "v3.458.2 : le nom du compagnon a toute la largeur, « Prêt » passe sous la barre");
  ok(/\.kf-back::after \{\s*content: ""; position: absolute;[^}]*width: max\(100%, 44px\); height: max\(100%, 44px\)/.test(css("00-components.css")), "zones de toucher de 44 px sur les petits boutons");
})();

/* [230] v3.448.6 — le palier Rare (ruines_13) dit ce qui manque et où le trouver ; l'établi de la Forge
   donne la provenance des matériaux manquants, une fois chacune. */
console.log("\n[230] v3.448.6 — Palier Rare : « Ce qui manque », et où");
(function () {
  var sv = { eq: game.equipped, gold: game.gold, vb: JSON.stringify(game.village || {}), fg: JSON.stringify(game.forge || {}), wr: game.worldsEverReached };
  try {
    var step = null; g.STORY_QUESTS.ruins.steps.forEach(function (s) { if (s.id === "ruines_13") step = s; });
    ok(step && typeof step.missing === "function", "ruines_13 porte missing()");
    g.VillageBuildingManager.ensure(); g.ForgeManager.ensure();
    game.village.buildings.forge = Object.assign({}, game.village.buildings.forge, { level: 3 });
    game.forge.levels.weapon = 6; game.gold = 0; game.worldsEverReached = { 0: true, 1: true, 2: true }; // aux Ruines
    game.equipped = { weapon: { slot: "weapon", rarity: "rare", name: "x", stat: "tapDmg", value: 10 } };
    var m = step.missing(game), txt = m.map(function (l) { return l.text + " | " + l.where; }).join("\n");
    ok(/Pièces Rares : 1 \/ 4/.test(txt) && /Sanctuaire scellé/.test(txt), "pièces Rares : le compte et d'où elles viennent");
    ok(/Forge 4 : Clé de voûte 0 \/ \d/.test(txt) && /Tailleur de pierre/.test(txt), "Forge 4 : la Clé de voûte et où la tailler");
    ok(/Reforge 7 de l'arme \| Il faut d'abord la Forge 4\./.test(txt), "reforge 7 : la Forge 4 d'abord");
    game.village.buildings.forge.level = 4;
    m = step.missing(game); txt = m.map(function (l) { return l.text + " | " + l.where; }).join("\n");
    ok(/Reforge 7 de l'arme : Clé de voûte/.test(txt), "Forge 4 bâtie : la reforge 7 liste ses matériaux manquants");
    var board = g.buildForgeBoardHTML(), acier = (board.match(/Acier : /g) || []).length;
    ok(acier === 1, "établi : la provenance de l'Acier n'apparaît qu'une fois (" + acier + ")");
    var q = fs.readFileSync(path.join(ROOT, "js/ui/quests-view.js"), "utf8");
    ok(/step\.missing\(game\)/.test(q) && /story-missing-title/.test(q), "la carte d'étape affiche « Ce qui manque »");
  } catch (err) {
    ok(false, "[230] exception : " + err.message);
  } finally {
    game.equipped = sv.eq; game.gold = sv.gold; game.village = JSON.parse(sv.vb); game.forge = JSON.parse(sv.fg); game.worldsEverReached = sv.wr;
  }
})();

/* [231] v3.448.7 — la puissance ennemie suit les PV effectifs ramenés au gabarit de la classe : le
   Chevalier n'est plus frappé plus fort parce qu'il encaisse mieux (Nuée 53 → 88 %). */
console.log("\n[231] v3.448.7 — Ajustement au héros : gabarit de PV effectifs par classe");
(function () {
  var CF = g.CombatForecast, d0 = CF.getHeroDamagePerRound, e0 = CF.getHeroEffectiveHp, h0 = game.heroId;
  try {
    ok(g.WORLD_HERO_SCALING.classEhpGabarit && g.WORLD_HERO_SCALING.classEhpGabarit.knight === 1.3, "gabarit du Chevalier : 1,3");
    CF.getHeroDamagePerRound = function () { return 300; }; CF.getHeroEffectiveHp = function () { return 1500; };
    var heroDe = function (cid) { var c = null; g.CLASSES.forEach(function (k) { if (k.id === cid) c = k; }); return c.heroIds[0]; };
    game.heroId = heroDe("knight"); var k = CF.getHeroScale("joueurDesert2", g.WORLD_HERO_SCALING);
    game.heroId = heroDe("mage"); var m = CF.getHeroScale("joueurDesert2", g.WORLD_HERO_SCALING);
    ok(Math.abs(m.power - Math.sqrt(1500 / 971 / 1.15)) < 1e-9, "Mage : puissance × (PV eff. / réf. / 1,15)^0,5 (×" + m.power.toFixed(3) + ")");
    ok(Math.abs(k.power - Math.max(1, Math.sqrt(1500 / 1.3 / 971 / 1.15))) < 1e-9 && k.power < m.power, "Chevalier : mêmes PV effectifs, puissance ramenée au gabarit (×" + k.power.toFixed(3) + ")");
    ok(k.hp === m.hp, "la part « PV des ennemis » ne dépend pas de la classe");
    var pa = CF.getHeroScale("joueurDesert2", { exp: 0.5, margin: 1.15, cap: 2.5 });
    ok(pa.power === m.power, "sans classEhpGabarit (Petites Aventures, Labyrinthe), rien ne change");
  } catch (err) {
    ok(false, "[231] exception : " + err.message);
  } finally { CF.getHeroDamagePerRound = d0; CF.getHeroEffectiveHp = e0; game.heroId = h0; }
})();

/* [232] v3.448.8 — une erreur dans un pas de boucle ne fige plus la partie : l'image suivante est
   toujours demandée, et chaque message n'est écrit qu'une fois en console. */
console.log("\n[232] v3.448.8 — Boucle de jeu protégée");
(function () {
  var raf0 = g.requestAnimationFrame, hud0 = g.renderHud, err0 = console.error, demandes = 0, ecrits = 0;
  try {
    g.requestAnimationFrame = function () { demandes++; };
    g.renderHud = function () { throw new Error("panne de test [232]"); };
    console.error = function () { ecrits++; };
    var t0 = game.playTime;
    g.lastTick = Date.now() - 100; g.gameLoop();
    g.lastTick = Date.now() - 100; g.gameLoop();
    ok(demandes === 2, "l'image suivante est demandée malgré l'erreur (" + demandes + "/2)");
    ok(game.playTime > t0, "le temps de jeu avance avant l'erreur");
    ok(ecrits === 1, "l'erreur n'est écrite qu'une fois (" + ecrits + ")");
  } catch (err) {
    ok(false, "[232] exception : " + err.message);
  } finally { g.requestAnimationFrame = raf0; g.renderHud = hud0; console.error = err0; }
})();

/* [233] v3.448.9 — plus de catch muet dans le jeu (noteErreur, une trace par lieu) ; une sauvegarde qui
   échoue faute de place prévient le joueur, au plus toutes les 5 minutes. */
console.log("\n[233] v3.448.9 — Erreurs rattrapées tracées, sauvegarde impossible signalée");
(function () {
  var muets = [], re = /catch\s*\(\s*\w+\s*\)\s*\{((?:\s|\/\/[^\n]*\n|\/\*[\s\S]*?\*\/)*)\}/g;
  require(path.join(__dirname, "index-scripts.js"))(ROOT).forEach(function (f) {
    var src = fs.readFileSync(path.join(ROOT, f), "utf8"), m;
    while ((m = re.exec(src))) muets.push(f + ":" + (src.slice(0, m.index).split("\n").length));
  });
  ok(muets.length === 0, "aucun catch muet dans les scripts du jeu" + (muets.length ? " — " + muets.join(", ") : ""));
  var w0 = console.warn, avert = 0; console.warn = function () { avert++; };
  try {
    g.noteErreur("[233].essai", new Error("a")); g.noteErreur("[233].essai", new Error("b"));
    ok(avert === 1 && g.erreursNotees["[233].essai"].n === 2, "noteErreur : une trace par lieu, les suivantes comptées");
  } finally { console.warn = w0; }
  var set0 = g.localStorage.setItem, toast0 = g.showToast, toasts = [];
  try {
    g.showToast = function (m) { toasts.push(m); };
    g.localStorage.setItem = function () { var e = new Error("plein"); e.name = "QuotaExceededError"; throw e; };
    run("sauvegardeImpossibleVueA = 0;");
    ok(run("saveGame()") === false, "stockage plein : saveGame renvoie false");
    ok(toasts.length === 1 && /mémoire du navigateur est pleine/.test(toasts[0]), "le joueur est prévenu");
    run("saveGame()");
    ok(toasts.length === 1, "pas de nouveau message avant 5 minutes");
    run("sauvegardeImpossibleVueA = Date.now() - 6 * 60 * 1000; saveGame();");
    ok(toasts.length === 2, "nouveau message après 5 minutes si ça dure");
  } catch (err) {
    ok(false, "[233] exception : " + err.message);
  } finally { g.localStorage.setItem = set0; g.showToast = toast0; run("sauvegardeImpossibleVueA = 0;"); }
})();

/* [234] v3.448.10 — icônes ramenées à 384 px au plus (affichées à 86 px au plus, ×3), anciens PNG de
   l'écran titre et de la barre supprimés, provenance de la Clé de voûte réécrite. */
console.log("\n[234] v3.448.10 — Images allégées (icônes), texte de la Clé de voûte");
(function () {
  function dims(f) { // largeur et hauteur d'un PNG, lues dans son en-tête IHDR
    var i = imgInfo(fs.readFileSync(f)); return [i.w, i.h];
  }
  var trop = [];
  (function walk(d) {
    fs.readdirSync(d).forEach(function (n) {
      var p = path.join(d, n);
      if (fs.statSync(p).isDirectory()) return walk(p);
      if (/\.(png|webp)$/i.test(n)) { var wh = dims(p); if (Math.max(wh[0], wh[1]) > 400) trop.push(path.relative(ROOT, p) + " " + wh.join("×")); }
    });
  })(path.join(ROOT, "images", "Icons"));
  ok(trop.length === 0, "aucune icône au-delà de 400 px (les lourdes ramenées à 384)" + (trop.length ? " — " + trop.slice(0, 5).join(", ") : ""));
  ok(["images/Borders/menu-bar-gold.png", "images/TitleScreen/title_background_new.png", "images/TitleScreen/titre_logo.png"].every(function (f) { return !fs.existsSync(path.join(ROOT, f)); }),
    "les trois PNG remplacés par du WebP (v3.448.3) sont supprimés");
  ok(g.WAREHOUSE_RESOURCES.cle_de_voute.sourceHint === "Se taille au Tailleur de pierre (Carrière), à partir de Pierres errantes et de Pierre", "provenance de la Clé de voûte réécrite");
})();

/* [235] v3.448.11 — les objets de combat se montrent dans le Sac (Consommables), avec les potions ; leur
   stock reste tenu par l'Entrepôt, qui ne les liste plus. */
console.log("\n[235] v3.448.11 — Objets de combat dans le Sac");
(function () {
  var avant = g.WarehouseManager.getAmount("baume_froid");
  try {
    g.WarehouseManager.addResource("baume_froid", 2, true);
    var e = g.getUnifiedInventoryEntries().filter(function (x) { return x.key === "item:baume_froid"; })[0];
    ok(e && e.type === "combatItem" && e.stock === avant + 2, "le Baume froid est une entrée du Sac, stock lu dans l'Entrepôt");
    run("selectedInventoryKey = 'item:baume_froid';");
    var fiche = g.buildUnifiedDetailPanelHTML(g.getUnifiedInventoryEntries());
    ok(/Baume froid/.test(fiche) && /Contre l(?:'|&#39;|&#x27;)Enragé/.test(fiche) && /Se prépare à l'Apothicaire/.test(fiche), "sa fiche : ce qu'il contre, d'où il vient, où il sert");
    ok(g.warehouseListedKeys().indexOf("baume_froid") === -1 && g.warehouseListedKeys().indexOf("ble") !== -1, "l'Entrepôt ne le liste plus (les ressources, si)");
    var src = fs.readFileSync(path.join(ROOT, "js/ui/heros-screens-view.js"), "utf8");
    ok(/\["potion", _t\("Consommables"\)/.test(src) && /COMBAT_ITEM_ORDER/.test(src), "Sac Héros : filtre « Consommables », objets de combat compris");
  } catch (err) {
    ok(false, "[235] exception : " + err.message);
  } finally { g.WarehouseManager.removeResource("baume_froid", 2); run("selectedInventoryKey = null;"); }
})();

/* [236] v3.449.0 — « Comme la dernière fois » : le dernier départ (potions à bonus, objets) est gardé dans la
   sauvegarde ; un toucher recoche ce qui est en stock et nomme ce qui manque. */
console.log("\n[236] v3.449.0 — « Comme la dernière fois » dans la préparation de sortie");
(function () {
  var sv = { last: game.lastSortiePrep, pots: JSON.stringify(game.potionsOwned || {}), huile: g.WarehouseManager.getAmount("huile_de_lame"), baume: g.WarehouseManager.getAmount("baume_froid") };
  try {
    var buff = g.POTIONS_DB.filter(function (p) { return p.perRun; })[0].id;
    game.lastSortiePrep = { buffs: [buff], items: ["huile_de_lame", "baume_froid"] };
    var data = JSON.parse(JSON.stringify(run("buildSaveData()")));
    ok(data.lastSortiePrep && data.lastSortiePrep.items.length === 2, "buildSaveData garde le dernier départ");
    game.lastSortiePrep = null;
    run("game.lastSortiePrep = restoreLastSortiePrep(" + JSON.stringify(data.lastSortiePrep) + ");");
    ok(game.lastSortiePrep && game.lastSortiePrep.buffs[0] === buff, "le chargement le rend");
    ok(run("restoreLastSortiePrep({ buffs: ['inconnue'], items: ['pas_un_objet'] })") === null, "le chargement écarte les identifiants inconnus");
    // État de stock : 1 potion, 1 Huile, 0 Baume
    game.potionsOwned[buff] = 1;
    g.WarehouseManager.removeResource("baume_froid", g.WarehouseManager.getAmount("baume_froid"));
    if (g.WarehouseManager.getAmount("huile_de_lame") < 1) g.WarehouseManager.addResource("huile_de_lame", 1, true);
    run("sortiePrep = { opts: { onGo: function () {} }, preset: null, buffs: {}, items: [], pick: -1 };");
    ok(/Comme la dernière fois/.test(run("buildSortiePrepAgainHTML()")), "le bouton s'affiche quand un départ est gardé");
    run("sortiePrepAgain();");
    var sp = run("sortiePrep");
    ok(sp.buffs[buff] === true && sp.items.indexOf("huile_de_lame") !== -1, "un toucher recoche la potion et l'Huile en stock");
    ok(sp.items.indexOf("baume_froid") === -1 && sp.againMissing.indexOf("baume_froid") !== -1, "le Baume, absent du stock, est nommé « Plus en stock »");
    run("closeSortiePrep(); fullResetState();");
    ok(game.lastSortiePrep === null, "« Effacer la partie » oublie le dernier départ");
    var src = fs.readFileSync(path.join(ROOT, "js/ui/sortie-prep-view.js"), "utf8");
    ok(/if \(buffsPris\.length \|\| objetsPris\.length\) game\.lastSortiePrep =/.test(src), "un départ sans potion ni objet n'efface pas le précédent");
  } catch (err) {
    ok(false, "[236] exception : " + err.message);
  } finally {
    run("sortiePrep = null;");
  }
})();

console.log("\n[237] v3.449.2 — Acide mordant renforcé (bouclier rongé à 25 %), Fiole noire sur l'or de fin de donjon");
(function () {
  try {
    var fs = require("fs");
    ok(g.COMBAT_ITEM_ACID_SHIELD_REDUCTION === 0.25 && g.BOSS_SHIELD_REDUCTION === 0.5, "bouclier : 50 % sans objet, 25 % rongé par l'Acide (option A1)");
    var eng = fs.readFileSync(ROOT + "/js/systems/combat-engine.js", "utf8");
    ok(/CombatItems\.holds\("shielded"\)\) \? COMBAT_ITEM_ACID_SHIELD_REDUCTION : BOSS_SHIELD_REDUCTION/.test(eng), "moteur : la réduction du bouclier lit l'Acide emporté");
    ok(/25 %/.test(g.COMBAT_ITEMS.acide_mordant.desc) && /donjon/.test(g.COMBAT_ITEMS.fiole_noire.con), "descriptions à jour (Acide, Fiole)");
    // Or de fin d'un donjon terminé, sans puis avec la Fiole bue
    function finDonjon(fiole) {
      game = freshCombat("knight"); giveWeapon(); game.dungeonRunsUsed = {};
      g.DungeonManager.start(1, []);
      game.sortie.loot.gold = 0; game.sortie.fioleUsed = !!fiole;
      var or0 = game.gold;
      g.DungeonManager.finish(true, g.DUNGEON_CONFIG.waveCount, "success");
      return game.gold - or0;
    }
    var plein = finDonjon(false), fiole = finDonjon(true);
    ok(plein > 0 && fiole === Math.floor(plein * 0.5), "donjon terminé : or de fin " + plein + ", divisé par deux si la Fiole a servi (" + fiole + ")");
    // Abandon : la sortie est close avant la récompense partielle, la Fiole se lit dans son résumé
    function abandon(fiole) {
      game = freshCombat("knight"); giveWeapon(); game.dungeonRunsUsed = {};
      g.DungeonManager.start(1, []); game.dungeonRun.wave = 9;
      game.sortie.loot.gold = 0; game.sortie.fioleUsed = !!fiole;
      var or0 = game.gold; g.DungeonManager.forfeit(); return game.gold - or0;
    }
    var ab = abandon(false), abF = abandon(true);
    ok(ab > 0 && abF === Math.floor(ab * 0.5), "abandon : récompense partielle " + ab + ", divisée par deux avec la Fiole (" + abF + ")");
  } catch (err) {
    ok(false, "[237] exception : " + err.message + " " + (err.stack || "").split("\n")[1]);
  }
})();

console.log("\n[238] v3.450.0 — Crypte, lot C-0 : socle et passage entre les mondes");
