    r.cuts = { "S>L0": "arbre" };
    ok(T.pa2_traps.condition(), "un sentier coupé en vue : la fenêtre s'ouvre");
    r.cuts = {}; r.traps = { "S>C0": { fx: "venin", hidden: true, seen: false, done: false } };
    ok(!T.pa2_traps.condition(), "un piège caché, invisible : pas encore");
    P.moveTo("C0");
