console.log("\n[287] v3.469.5 — Petites Aventures : trois reliques par monde (PA-R2)");
(function () {
  var S = g.SceneRunManager, P = g.Pa2Run, R = g.PA2_RULES, RL = g.PA2_RELICS;
  var TPL = { forest: "petite_aventure_foret", desert: "petite_aventure_desert", ruins: "petite_aventure_ruines", crypt: "petite_aventure_crypte" };
  function prep() {
    game = freshCombat("knight"); giveWeapon(); run("game.enemy = null; game.combat = null;");
    S.ensureDefaults(); game.explorationProgression.petiteAventure = { spent: 0, since: null };
    game.resources.petite_ration = 5; game.heroLevel = 12; game.heroHp = game.heroMaxHp; game.sceneRun = null;
    if (g.SortieManager.isActive()) g.SortieManager.end("return");
  }
  function go(world, relics, items) { prep(); S.startRun(TPL[world]); var r = game.sceneRun; r.hookId = null; (items || []).forEach(function (id) { P.addItem(id); }); P.depart(); r.cuts = {}; r.traps = {}; r.relics = (relics || []).slice(); return r; }
  try {
    var byW = {}; Object.keys(RL).forEach(function (id) { if (RL[id].world) (byW[RL[id].world] = byW[RL[id].world] || []).push(RL[id].rar); });
    ok(["desert", "ruins", "crypt"].every(function (w) { return (byW[w] || []).sort().join() === "com,leg,rare"; }), "trois reliques par monde : une commune, une rare, une légendaire");
    var okW = true;
    Object.keys(TPL).forEach(function (w) { var r = go(w); for (var k = 0; k < 60; k++) P.drawRelics(r, 3).forEach(function (id) { if (RL[id].world && RL[id].world !== w) okW = false; }); });
    var seenD = {}; var rD = go("desert"); for (var k = 0; k < 300; k++) P.drawRelics(rD, 3).forEach(function (id) { seenD[id] = 1; });
    ok(okW && seenD.perle && seenD.scarabee && seenD.dune, "une relique de monde ne se tire que dans son monde (et le Désert tire les siennes)");
    var r = go("desert"), b = r.breath; P.moveTo(P.openMoves()[0]); var st0 = b - r.breath;
    r = go("desert", ["perle"]); b = r.breath; P.moveTo(P.openMoves()[0]);
    ok(b - r.breath === st0 - R.perleStep, "Perle de rosée : un Souffle de moins par pas");
    r = go("desert"); var rb0 = P.ruseBonus(r); r = go("desert", ["scarabee"]); var rb1 = P.ruseBonus(r); r = go("crypt", ["cloche"]); var rb2 = P.ruseBonus(r);
    ok(rb1 === rb0 + 1 && rb2 === rb0 + 2, "Œil de scarabée : Ruser +1 ; Cloche muette : +2");
    r = go("desert"); var s0 = P.sourceAmount(r); r = go("desert", ["dune"]);
    ok(P.sourceAmount(r) === Math.round(s0 * R.duneSource), "Cœur de dune : les points d'eau rendent la moitié");
    r.status = "pa2-node"; P.finish("home");
    ok(Math.abs(r.end.mult - R.duneLoot) < 1e-9, "Cœur de dune : butin final ×1,25");
    r = go("ruins"); var tk = r.at + ">" + P.openMoves()[0]; r.traps[tk] = { fx: "venin", hidden: false, seen: true, done: false }; P.moveTo(tk.split(">")[1]); var d0 = P.trapOptions().disarm.bonus;
    r = go("ruins", ["clou"]); r.traps[tk] = { fx: "venin", hidden: false, seen: true, done: false }; P.moveTo(tk.split(">")[1]);
    ok(P.trapOptions().disarm.bonus === d0 + 1, "Clou de bâtisseur : désamorcer +1 cran");
    r = go("ruins", ["fil"]); var savedRand = P.rand; P.rand = function () { return 0; }; var sh = P._shiftWalls(r); P.rand = savedRand;
    ok(sh === null, "Fil d'Edda : les murs ne bougent plus");
    function obstacleAt(r) { var o = r.nodes[Object.keys(r.nodes).filter(function (x) { return r.nodes[x].row === 1; })[0]]; o.type = "obstacle"; o.gabaritId = null; o.done = false; r.at = o.key; r.status = "pa2-node"; P._prepareNode(r, o); return o; }
    r = go("ruins"); var o0 = obstacleAt(r), bz = P.obstacleOptions().map(function (o) { return o.bonus; }), cn = r.nodes[r.at], m0 = P._dmgMult(r, cn, "tenir");
    r = go("ruins", ["marteau"]); var o1 = obstacleAt(r); o1.gabaritId = o0.gabaritId; o1.diff = o0.diff;
    ok(P.obstacleOptions().every(function (o, i) { return o.bonus === bz[i] + 1; }) && Math.abs(P._dmgMult(r, cn, "tenir") / m0 - R.marteauDmg) < 1e-9, "Marteau du Contremaître : +1 cran sur toutes les voies, combats +15 %");
    r = go("crypt", ["meche"], ["lanterne"]); P.useItem("lanterne"); var l1 = r.lanternLeft; r = go("crypt", [], ["lanterne"]); P.useItem("lanterne");
    ok(l1 === r.lanternLeft + R.mecheSteps, "Mèche de Sarkel : la Lanterne brûle 3 pas de plus");
    r = go("crypt", ["cendre"]); r.loot = 500; var a = r.nodes[Object.keys(r.nodes).filter(function (x) { return r.nodes[x].row === 1; })[0]]; a.type = "autel"; a.done = false; r.at = a.key; r.status = "pa2-node"; game.heroHp = 1;
    var al = P.altar(true);
    ok(P.altarCost(r) === 0 && al.ok && al.result.cost === 0 && al.result.healed === Math.round(game.heroMaxHp * R.altarHealPct * R.cendreHeal), "Cendre de veilleur : alcôves gratuites, soin double");
    r = go("crypt", ["cloche"]); var res = {}; P._applyTrapFx(r, "alarme", res);
    ok(!r.fx.alarme && res.muted, "Cloche muette : l'Alarme ne sonne pas");
  } finally {
    game.sceneRun = null; if (g.SortieManager.isActive()) g.SortieManager.end("return");
  }
})();

console.log("\n[288] v3.469.6 — Petites Aventures : le gardien ne prend que la moitié du renfort de l'anneau (Périple)");
(function () {
  var S = g.SceneRunManager, P = g.Pa2Run;
  game = freshCombat("knight"); giveWeapon(); run("game.enemy = null; game.combat = null;");
  S.ensureDefaults(); game.explorationProgression.petiteAventure = { spent: 0, since: null }; game.heroLevel = 12; game.sceneRun = null;
  if (g.SortieManager.isActive()) g.SortieManager.end("return");
  try {
    S.startRun("petite_aventure_desert"); var r = game.sceneRun; P.depart();
    var bk = Object.keys(r.nodes).filter(function (k) { return r.nodes[k].type === "boss"; })[0], bn = r.nodes[bk];
    var cn = { key: "x", type: "combat", act: 3, row: 8, foeId: g.PA2_FOES.desert[3][0], pack: 1 };
    r.ring = "sentier"; var g1 = P._foe(r, bn).maxHp, c1 = P._foe(r, cn).maxHp;
    r.ring = "periple"; var g3 = P._foe(r, bn).maxHp, c3 = P._foe(r, cn).maxHp;
    r.ring = "chemin"; var g2 = P._foe(r, bn).maxHp;
    ok(Math.abs(g3 / g1 - 1.375) < 0.01 && Math.abs(g2 / g1 - 1.15) < 0.01, "gardien : ×1,15 au Chemin, ×1,375 au Périple (" + (g2 / g1).toFixed(3) + ", " + (g3 / g1).toFixed(3) + ")");
    ok(Math.abs(c3 / c1 - g.PA2_RINGS.periple.foeMult) < 0.01, "les autres combats gardent le renfort entier (×1,75)");
  } finally { game.sceneRun = null; if (g.SortieManager.isActive()) g.SortieManager.end("return"); }
})();

console.log("\n[289] v3.470.0 — Donjons : un unique par boss, à pouvoir signature");
(function () {
  game = freshCombat("knight");
  var D = g.DungeonManager, SQ = g.StoryQuestManager, reach = SQ.isStepReached, C = g.DUNGEON_CONFIG;
  var attendus = { 1: "dun_mue", 2: "dun_enigme", 3: "dun_garde", 4: "dun_sepulcre" };
  Object.keys(attendus).forEach(function (id) {
    var u = D.getById(Number(id)).boss.unique, p = u && g.LEGENDARY_POWER_BY_ID[u.power];
    ok(u && u.power === attendus[id] && p && p.label && p.desc && g.EQUIPMENT_SLOT_CONFIG[u.slot], "donjon " + id + " : unique « " + (u && u.name) + " », pouvoir " + attendus[id] + " décrit");
  });
  // pouvoirs : sans objet porté, aucun effet ; porté, l'effet contré est divisé par deux
  var en = { archetype: "corrupted" };
  var corr0 = g.getCorruptedDamageMultiplier(4, en), rage0 = g.getEnragedDamageMultiplier(0.8, en), vamp0 = g.getVampiricLifestealAmount(1000, en);
  ok(g.powerMultOf("dun_mue") === 1, "powerMultOf : 1 sans l'objet");
  game.equipped.armor = { uid: "t_mue", slot: "armor", name: "Écailles du Basilic", rarity: "common", stat: "defense", value: 0.01, affixes: [], power: "dun_mue", unique: true };
  game.equipped.boots = { uid: "t_garde", slot: "boots", name: "Bottes du Garde scellé", rarity: "common", stat: "autoDps", value: 1, affixes: [], power: "dun_garde", unique: true };
  game.equipped.gloves = { uid: "t_sep", slot: "gloves", name: "Gants du fossoyeur", rarity: "common", stat: "tapMult", value: 0.01, affixes: [], power: "dun_sepulcre", unique: true };
  ok(Math.abs((1 - g.getCorruptedDamageMultiplier(4, en)) - (1 - corr0) / 2) < 1e-9, "Peau de mue : la perte de dégâts du Corrupteur est divisée par deux");
  ok(Math.abs((g.getEnragedDamageMultiplier(0.8, en) - 1) - (rage0 - 1) / 2) < 1e-9, "Pas du Garde : le bonus de rage est divisé par deux");
  ok(g.getVampiricLifestealAmount(1000, en) === Math.floor(vamp0 / 2) || g.getVampiricLifestealAmount(1000, en) === Math.floor(vamp0 * 0.5), "Sépulcre : le vol de vie est divisé par deux");
  game.equipped.armor = null; game.equipped.boots = null; game.equipped.gloves = null;
  // Énigme : le premier télégraphe du combat échoue, le second passe ; un nouveau combat la recharge
  game.equipped.amulet = { uid: "t_eni", slot: "amulet", name: "Amulette de l'énigme", rarity: "common", stat: "critChance", value: 1, affixes: [], power: "dun_enigme", unique: true };
  var e = { name: "Cible", hp: 100, maxHp: 100, isBoss: true, stats: { power: 10 } };
  g.CombatActors.setEnemies([e]); game.enemy = e; g.CombatEngine.prepareEnemy(e);
  g.CombatEngine.telegraphPattern(e, "charge");
  ok(!e.chargeTelegraphed && e.chargeIn > 0 && e.counteredRounds > 0, "Énigme : la première charge échoue, son compte à rebours repart");
  g.CombatEngine.telegraphPattern(e, "heal");
  ok(e.healTelegraphed === true, "Énigme : le second télégraphe du combat passe");
  var e2 = { name: "Cible 2", hp: 100, maxHp: 100, isBoss: true, stats: { power: 10 } };
  g.CombatActors.setEnemies([e2]); game.enemy = e2; g.CombatEngine.prepareEnemy(e2);
  g.CombatEngine.telegraphPattern(e2, "surge");
  ok(e2.surgeTelegraphed === true, "Énigme : l'exaltation d'élite n'est jamais annulée");
  g.CombatEngine.telegraphPattern(e2, "shield");
  ok(!e2.shieldTelegraphed, "Énigme : rechargée au combat suivant (bouclier annulé)");
  game.equipped.amulet = null;
  // tirage en fin de run : réussite seulement (mode libre compris), à la rareté du butin de fin
  var pv = { check: g.ProvisionsManager.check, consume: g.ProvisionsManager.consume }, pct = C.uniqueDropPct;
  run("ProvisionsManager.check = function () { return null; }; ProvisionsManager.consume = function () {};");
  SQ.isStepReached = function () { return true; };
  game.worldsEverReached = { 0: true };
  var fin = function (ok_, free) {
    game.heroHp = game.heroMaxHp; game.dungeonRunsUsed = {}; game.inventory = []; game.dungeonTierCleared = { 1: true };
    D.start(1, [], 1, !!free);
    D.finish(ok_, ok_ ? 15 : 3, ok_ ? "success" : "flee");
    return game.inventory.filter(function (it) { return it.dungeonUniqueId; });
  };
  C.uniqueDropPct = 100;
  var got = fin(true);
  ok(got.length === 1 && got[0].power === "dun_mue" && got[0].unique === true && got[0].name === "Écailles du Basilic" && got[0].slot === "armor" && got[0].rarity === "common", "réussite à 100 % : les Écailles du Basilic tombent (Commun à la Tanière 1, unique)");
  ok(fin(false).length === 0, "fuite : pas d'unique");
  ok(fin(true, true).length === 1, "mode libre : l'unique peut tomber aussi");
  C.uniqueDropPct = 0;
  ok(fin(true).length === 0, "à 0 % : rien");
  C.uniqueDropPct = pct;
  ok(pct === 5, "taux par défaut : 5 % par run réussi");
  var html = g.buildDungeonSummaryHTML({ success: true, tierName: "Tanière du Basilic", clearedWave: 15, wavesTotal: 15, goldReward: 1, shardsGained: 1, lootedUnique: got[0] });
  ok(html.indexOf("Objet unique") >= 0 && html.indexOf("Écailles du Basilic") >= 0 && html.indexOf("Peau de mue") >= 0, "rapport de fin : ligne « Objet unique » avec le pouvoir");
  game.inventory = [];
  SQ.isStepReached = reach; g.ProvisionsManager.check = pv.check; g.ProvisionsManager.consume = pv.consume;
})();

console.log("\n[290] v3.470.1 — Télégraphes : plus de toast, le bandeau suffit (retour Seb)");
